import{_ as i,c as t,o as r,a5 as a}from"./chunks/framework.DuCYAsAJ.js";const g=JSON.parse('{"title":"点赞与取消点赞系统","description":"","frontmatter":{"title":"点赞与取消点赞系统","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#4.1","branch":"main","level":1,"order":4.1},"headers":[],"relativePath":"posts/projects/zfeed/04-interaction-rpc-service/01-like-and-unlike-system.md","filePath":"posts/projects/zfeed/04-interaction-rpc-service/01-like-and-unlike-system.md","lastUpdated":1779632679000}'),n={name:"posts/projects/zfeed/04-interaction-rpc-service/01-like-and-unlike-system.md"};function l(o,e,c,s,p,h){return r(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="点赞与取消点赞系统" tabindex="-1">点赞与取消点赞系统 <a class="header-anchor" href="#点赞与取消点赞系统" aria-label="Permalink to &quot;点赞与取消点赞系统&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/cancel_like_user_hash.lua" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/cancel_like_user_hash.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/like_user_hash.lua" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/like_user_hash.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/do/like_do.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/do/like_do.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/batchislikedlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/batchislikedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/batchlikeinfologic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/batchlikeinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/cache.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/cache.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/querylikeinfologic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/querylikeinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/querylikeinfologic_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/querylikeinfologic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go</a></li></ul></details><p><code>interaction-rpc</code> 中的点赞与取消点赞系统，为用户对内容（文章、视频）和评论的互动提供高性能、最终一致的机制。它采用多层方案：使用 Redis 完成低延迟的原子状态转换，通过 Transactional Outbox 可靠投递事件，并使用带版本字段的幂等数据库更新处理乱序消息。</p><h2 id="系统架构与数据流" tabindex="-1">系统架构与数据流 <a class="header-anchor" href="#系统架构与数据流" aria-label="Permalink to &quot;系统架构与数据流&quot;">​</a></h2><p>系统分为写路径（Request -&gt; Cache -&gt; Outbox）和后台 relay 路径（Outbox -&gt; Kafka -&gt; Consumer -&gt; DB）。</p><h3 id="互动流程图" tabindex="-1">互动流程图 <a class="header-anchor" href="#互动流程图" aria-label="Permalink to &quot;互动流程图&quot;">​</a></h3><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go#L35-L64" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go#35-64</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L34-L45" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#34-45</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer.go#L42-L65" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer.go#42-65</a></p><h2 id="核心实现细节" tabindex="-1">核心实现细节 <a class="header-anchor" href="#核心实现细节" aria-label="Permalink to &quot;核心实现细节&quot;">​</a></h2><h3 id="原子状态转换-redis-lua" tabindex="-1">原子状态转换（Redis Lua） <a class="header-anchor" href="#原子状态转换-redis-lua" aria-label="Permalink to &quot;原子状态转换（Redis Lua）&quot;">​</a></h3><p>为了保证高并发安全并避免竞态条件（例如快速连续点击两次点赞），系统使用 Redis Lua 脚本。用户点赞状态存储在一个 Hash 中，其中 field 由 scene 和 content ID 组合而成：<code>[scene:content_id]</code>。</p><ul><li>点赞脚本：将 field 设置为 <code>&quot;1&quot;</code>。只有当原状态不是 <code>&quot;1&quot;</code> 时，才返回 <code>changed=1</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/like_user_hash.lua#L19-L30" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/like_user_hash.lua#19-30</a></li><li>取消点赞脚本：将 field 设置为 <code>&quot;0&quot;</code>。当原状态是 <code>&quot;1&quot;</code> 时，返回 <code>changed=1</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/cancel_like_user_hash.lua#L16-L18" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/cancel_like_user_hash.lua#16-18</a></li></ul><h3 id="transactional-outbox-与回滚" tabindex="-1">Transactional Outbox 与回滚 <a class="header-anchor" href="#transactional-outbox-与回滚" aria-label="Permalink to &quot;Transactional Outbox 与回滚&quot;">​</a></h3><p>当 Redis 中检测到状态变更后，服务会尝试把事件持久化到 <code>zfeed_like_event_outbox</code> 表。如果事件发布失败（例如数据库错误），系统会回滚缓存，使 Redis 状态与上一次已知的持久化状态保持一致。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go#L57-L60" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go#57-60</a></p><h3 id="缓存缺失时回退数据库" tabindex="-1">缓存缺失时回退数据库 <a class="header-anchor" href="#缓存缺失时回退数据库" aria-label="Permalink to &quot;缓存缺失时回退数据库&quot;">​</a></h3><p>如果用户的点赞状态在 Redis 中缺失（例如缓存过期），系统会回退到 MySQL 数据库判断当前状态，然后再更新缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go#L94-L104" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go#94-104</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go#L66-L89" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go#66-89</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go#L68-L105" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go#68-105</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/cache.go#L39-L48" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/cache.go#39-48</a></p><h2 id="数据库表结构与幂等性" tabindex="-1">数据库表结构与幂等性 <a class="header-anchor" href="#数据库表结构与幂等性" aria-label="Permalink to &quot;数据库表结构与幂等性&quot;">​</a></h2><p><code>zfeed_like</code> 表使用唯一键 <code>uk_user_scene_content</code> 防止重复记录。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L115-L122" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#115-122</a></p><h3 id="带版本字段的幂等-upsert" tabindex="-1">带版本字段的幂等 Upsert <a class="header-anchor" href="#带版本字段的幂等-upsert" aria-label="Permalink to &quot;带版本字段的幂等 Upsert&quot;">​</a></h3><p>为了处理 Kafka 消息重投递或事件乱序，<code>Upsert</code> 逻辑使用 <code>last_event_ts</code>（版本字段）。只有当传入事件时间戳大于或等于数据库中当前保存的时间戳时，状态才会更新。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> zfeed_like (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  user_id, scene, content_id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, last_event_ts, ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (?, ?, ?, ?, ?, ...)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DUPLICATE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UPDATE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(last_event_ts) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> last_event_ts, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  last_event_ts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> GREATEST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(last_event_ts, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(last_event_ts)),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(last_event_ts) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> last_event_ts, CURRENT_TIMESTAMP, updated_at)</span></span></code></pre></div><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L46-L79" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#46-79</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L112-L161" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#112-161</a></p><h2 id="实体空间映射" tabindex="-1">实体空间映射 <a class="header-anchor" href="#实体空间映射" aria-label="Permalink to &quot;实体空间映射&quot;">​</a></h2><p>下图将高层概念映射到 <code>interaction-rpc</code> 服务中的具体代码实体。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go#L17-L33" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go#17-33</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L24-L30" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#24-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer.go#L23-L31" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer.go#23-31</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/do/like_do.go#L3-L16" target="_blank" rel="noreferrer">app/rpc/interaction/internal/do/like_do.go#3-16</a></p><h2 id="关键组件总结" tabindex="-1">关键组件总结 <a class="header-anchor" href="#关键组件总结" aria-label="Permalink to &quot;关键组件总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>文件引用</th></tr></thead><tbody><tr><td><code>LikeLogic</code></td><td>编排点赞流程、缓存更新和事件触发。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go</a></td></tr><tr><td><code>UnlikeLogic</code></td><td>编排取消点赞流程，并在缓存缺失时回退数据库。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go</a></td></tr><tr><td><code>LikeRepository</code></td><td>处理 <code>zfeed_like</code> 表的 MySQL CRUD 操作。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go</a></td></tr><tr><td><code>LikeConsumer</code></td><td>幂等消费 Kafka 事件，更新最终数据库状态。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer.go</a></td></tr><tr><td><code>Lua Scripts</code></td><td>确保 Redis 中用户点赞状态的原子 check-and-set。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/likelogic.go#L17-L23" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/likelogic.go#17-23</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/like/unlikelogic.go#L17-L24" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/like/unlikelogic.go#17-24</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L32-L36" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#32-36</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer.go#L23-L28" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer.go#23-28</a></p>`,28)])])}const b=i(n,[["render",l]]);export{g as __pageData,b as default};
